#include "tigersheets/session.hpp"
#include <QCoreApplication>
#include <QFile>
#include <QProcess>
#include <QTemporaryDir>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
Json request(){return Json::parse(R"json({"version":1,"kind":"workbook_tool","contextGeneration":41,"retainedLinks":[],"previousProposal":[],"tool":"workbook_v1_capabilities","args":{},"workbook":{"revision":0,"sheets":[{"id":"s","name":"Data","cells":[{"row":1,"col":1,"input":"Region"},{"row":1,"col":2,"input":"Revenue"},{"row":2,"col":1,"input":"East"},{"row":2,"col":2,"input":"=3+4"},{"row":3,"col":1,"input":"West"},{"row":3,"col":2,"input":"11"}]},{"id":"r","name":"Report","cells":[]}]}})json");}
Json pivot(){return Json::parse(R"json({"type":"create_pivot","definition":{"id":"p","name":"RevenueReport","source":{"sheet":"s","row1":1,"col1":1,"row2":3,"col2":2},"rows":[{"field":"Region"}],"values":[{"field":"Revenue","aggregate":"sum","name":"Revenue"}],"output":{"sheet":"r","row1":1,"col1":1}}})json");}
Json run(const QString& executable,const Json& value){QTemporaryDir dir;const auto input=dir.filePath("request.json"),output=dir.filePath("response.json");QFile file(input);require(file.open(QIODevice::WriteOnly),"write private tool request");file.setPermissions(QFile::ReadOwner|QFile::WriteOwner);file.write(QByteArray::fromStdString(value.dump()));file.close();QProcess process;process.start(executable,{"--request",input,"--response",output});require(process.waitForFinished(30000),"tool worker finishes");require(process.exitCode()==0,"tool worker returns a protocol result");QFile response(output);require(response.open(QIODevice::ReadOnly),"tool worker publishes a result file");return Json::parse(response.readAll().toStdString());}
void toolWorkflow(const QString& executable){auto input=request();auto result=run(executable,input);require(result.value("status",std::string())=="ok"&&result.contains("toolReply")&&result["toolReply"]["version"]=="workbook.v1","worker supports isolated workbook tool requests without a pivot definition");require(result["revision"]==0&&result["contextGeneration"]==41&&result["operations"].empty(),"tool replies preserve the captured revision/context without authoring edits");
 input["tool"]="workbook_v1_preview";input["args"]={{"revision",0},{"operations",Json::array({pivot(),{{"type","create_pivot_chart"},{"pivotId","p"},{"id","pc"},{"chartType","column"}}})}};result=run(executable,input);require(result["status"]=="ok"&&result["toolReply"]["status"]=="preview"&&result["operations"].size()==2,"tool worker composes real native report and PivotChart operations");const auto& definition=result["operations"][0]["definition"];require(definition["layout"]["grandTotals"][0]["value"]==18&&definition["cache"]["contextGeneration"]==41&&definition.contains("provenance"),"tool reports calculate source formulas and retain context provenance");
 input["previousProposal"]=result["operations"];input["args"]={{"revision",0},{"operations",Json::array({{{"type","update_pivot"},{"id","p"},{"changes",{{"filters",Json::array({{{"field","Region"},{"all",false},{"items",Json::array({{{"type","string"},{"value","East"}}})}}})}}}}})}};result=run(executable,input);require(result["toolReply"]["status"]=="preview"&&result["operations"].size()==3,"another isolated tool call composes with the previous proposal at the live base revision");
 input["previousProposal"]=result["operations"];input["tool"]="workbook_v1_report";input["args"]={{"id","p"}};result=run(executable,input);require(result["toolReply"]["view"]=="preview"&&result["toolReply"]["data"][0][0]["value"]==7,"subsequent report reads inspect the combined pending proposal");require(result["operations"].empty(),"bounded report reads must not retransmit the full pending cache operations");
}
void cachedInputs(const QString& executable){auto input=request();input["tool"]="workbook_v1_preview";input["args"]={{"revision",0},{"operations",Json::array({pivot()})}};input["workbook"]["sheets"][0]["cells"][3]["input"]="='[Missing.xlsx]Inputs'!A1";input["workbook"]["links"]=Json::parse(R"json([{"name":"Missing.xlsx","path":"/never-read/Missing.xlsx","enabled":true,"cachedWorkbook":{"revision":0,"sheets":[{"id":"i","name":"Inputs","cells":[{"row":1,"col":1,"input":"7"}]}]}}])json");auto denied=run(executable,input);require(denied["status"]=="ok"&&denied["toolReply"].contains("error")&&denied["operations"].empty(),"isolated report tools refuse cached financial inputs without a host grant");input["allowCachedLinks"]=true;auto allowed=run(executable,input);require(allowed["toolReply"]["status"]=="preview"&&allowed["operations"][0]["definition"]["provenance"]["links"][0]["state"]=="cached","explicit current host grants retain saved-source provenance in isolated jobs");}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{require(argc==2,"Pass the native report worker executable");toolWorkflow(QString::fromLocal8Bit(argv[1]));cachedInputs(QString::fromLocal8Bit(argv[1]));std::cout<<"report worker tool tests passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
